"""Read-only analysis of saved seed1 negative samples; no optimization or SDP."""
import json,time,hashlib
import numpy as np
import mpmath as mp
from scipy.spatial import cKDTree
from negative_valley_seed1_2026_search import ROOT,components
from sharp_contact_refinement2026_export import mpR
from sharp_contact_refinement2026_refine import IndependentActual
PREFIX='negative_valley_seed1_2026_'

def main():
    start=time.monotonic();source=ROOT/(PREFIX+'data.json');d=json.loads(source.read_text());model=json.loads((ROOT/'sharp_contact_refinement2026_results.json').read_text())['best_solution'];actual=IndependentActual([np.array(a) for a in model['A']],model['c']);mp.mp.dps=80
    p=np.array(d['negative_points']);v=np.array(d['negative_R']);label,n=components(p,d['cluster_radius']);groups=sorted([np.flatnonzero(label==j) for j in range(n)],key=lambda ix:min(v[ix]));labels=np.zeros(len(p),dtype=int);rows=[]
    for i,(row,ix) in enumerate(zip(d['valleys'],groups),1):
        labels[ix]=i;row=dict(row);c=np.array(row['center_minimum_sample']);r,g=actual(c,True);h=1e-4;H=np.column_stack([(actual(c+np.eye(3)[j]*h,True)[1][0]-actual(c-np.eye(3)[j]*h,True)[1][0])/(2*h) for j in range(3)]);H=(H+H.T)/2;e,Q=np.linalg.eigh(H);hp=mpR(model['A'],model['c'],c)
        row['unique_negative_sample_count_round12']=len(np.unique(np.round(p[ix],12),axis=0));row['high_precision_actual_f']=hp;row['gradient_numeric']=g[0].tolist();row['Hessian_numeric_central_gradient_step_1e4']=H.tolist();row['Hessian_eigenvalues_numeric']=e.tolist();row['Hessian_eigenvectors_columns_numeric']=Q.tolist()
        if min(e)>0:
            half=np.sqrt(-2*r[0]*np.diag(np.linalg.inv(H)));row['local_quadratic_ellipsoid_halfaxes']=np.sqrt(-2*r[0]/e).tolist();row['local_quadratic_ellipsoid_coordinate_halfwidth']=half.tolist();row['local_quadratic_coordinate_box_min']=(c-half).tolist();row['local_quadratic_coordinate_box_max']=(c+half).tolist()
        row['quadratic_warning']='Local Taylor approximation at the sampled minimum, not an extent guarantee or certified bound.';rows.append(row)
    distances=[]
    for i in range(len(groups)):
        for j in range(i+1,len(groups)):distances.append({'valley_ids':[i+1,j+1],'minimum_sample_distance':float(min(cKDTree(p[groups[j]]).query(p[groups[i]],k=1)[0]))})
    out={'warning':d['warning'],'source_data':str(source),'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'model':d['model'],'domain':d['domain'],'search_elapsed_seconds':d['elapsed_seconds'],'search_seed_count':d['optimization_count'],'job':{'id':'bash-694','status':'completed exit0','collected_with_job_output':True},'no_SDP':True,'valleys':rows,'negative_point_cluster_ids':labels.tolist(),'sample_cluster_distances':distances,'cluster_sensitivity':d['cluster_sensitivity'],'negative_sample_records':len(p),'unique_negative_sample_count_round12':len(np.unique(np.round(p,12),axis=0)),'shallow_negative_count_minus1e9_to_zero':d['shallow_negative_count_minus1e9_to_zero'],'scope_limit':'12 starts and sampling reveal three separated sample clusters, with no completeness proof. Shallow negative points above -1e-9 are not clustered. T-box exclusion of one center does not cover the entire sample cluster.','analysis_elapsed_seconds':time.monotonic()-start}
    target=ROOT/(PREFIX+'summary.json');assert not target.exists();target.write_text(json.dumps(out,indent=2)+'\n')
    lines=['# 第一 PSD seed 的负残差谷发现','', '**Discovery only。** 本次不解 SDP；使用第一批 `best_solution`（round2）的 original A/c 与 actual Coulomb f。12 个不同起点在 %.3f 秒内完成，发现三个相隔较远的负样本簇。旧 T 谷中心被父线程严格排除九点竞争延拓，但另两个负谷尚需单独分析。'%d['elapsed_seconds'],'','## 模型与搜索范围','', '模型：[sharp_contact_refinement2026_results.json](</home/dsh/Thomson Problem/proof_work/sharp_contact_refinement2026_results.json>) 的 `best_solution`，iteration2；SHA256 `%s`，c=%.16g，trace=%.12g，minB=%.12g。'%(d['model']['sha256'],model['c'],model['trace'],model['min_B_eigenvalue']), '', '按排序 -1<=u<=v<=t<0.56、Gram>=0、Ckernel>=0 搜索。旧竞争条件 C 没有强加，但所有三个负簇的每个已保存负样本均满足旧 C>=0。没有做真根 r* 的严格校正；父线程报告其误差约1e-11，这只能支持本次数值发现的量级判断。', '', '既有三批只复用训练/验证点坐标，没有使用第二、第三批的核。加7000随机内部、2500边界、4000个v=t截面与旧T附近3000点。74,217个几何有效去重点中21,859满足Ckernel>=0，初扫1766个R<-1e-9。8个SLSQP独立起点，加4个DE随机种子；DE分别覆盖全域u、u∈[-1,-.6]、[-.6,-.2]、[-.2,.56]。每个DE均无polish；u∈[-.6,-.2]的DE在100迭代未收敛、返回等边接触附近R≈0，其余3个DE收敛。', '', '原始残差由六置换正确Q递推直接计算，不使用h11。汇总另用80位mpmath对各中心的同一有限JSON十进制A/c/坐标复算，仅为高精度数值检查。', '', '## 三个负样本簇','', '| 簇 | 最深样本中心(u,v,t) | R | Gram | Ckernel | 样本记录数 |','|---|---|---:|---:|---:|---:|']
    for row in rows:lines.append('| %d | (%s) | %.12g | %.10g | %.12g | %d |'%(row['id'],', '.join('%.10f'%x for x in row['center_minimum_sample']),row['depth_R'],row['Gram_center'],row['Ckernel_center'],row['negative_sample_count']))
    lines+=['','以下区间只包住已采到的 R<-1e-9 点，**不是负域外包，也不是覆盖证书**。','']
    for row in rows:
        lines+=['- 簇%d：u∈[%.10f, %.10f]，v∈[%.10f, %.10f]，t∈[%.10f, %.10f]；距最深样本最大采样半径 %.10f。'%(row['id'],row['sample_bbox_min'][0],row['sample_bbox_max'][0],row['sample_bbox_min'][1],row['sample_bbox_max'][1],row['sample_bbox_min'][2],row['sample_bbox_max'][2],row['max_sample_radius_from_center'])]
    lines+=['','簇2接近全对称u=v=t截面；簇3接近v=t截面。簇1沿v方向明显较长。80位残差分别为：','']
    for row in rows:lines.append('- 簇%d：`%s`。'%(row['id'],row['high_precision_actual_f']['R_decimal_80digit']))
    lines+=['','## 范围解释与后续严格覆盖的用途','', '邻接聚类半径0.035和0.06时均为3簇；0.02时4簇、0.01时7簇，表明较小半径会把稀疏采样的同一谷切碎。保存2402条负点记录（可能重复），其中%d个坐标去重至12位；另有19条-1e-9<=R<0浅负记录未纳入聚类，可能含接触处舍入误差。'%out['unique_negative_sample_count_round12'], '', '汇总JSON还保存每中心的数值梯度、差分Hessian和局部二次椭球半轴。这些仅供选择初始Tbox大小，不能替代区间覆盖。建议分别处理三个簇；旧T点的排除证书不能自动扩展到整个簇1，更不能覆盖簇2、3。并未证明不存在更浅、更窄或未采到的其他负谷。', '', '## 可复现文件','', '- [negative_valley_seed1_2026_search.py](</home/dsh/Thomson Problem/proof_work/negative_valley_seed1_2026_search.py>)：有174秒内部截止、最多12起点、无SDP；[negative_valley_seed1_2026_data.json](</home/dsh/Thomson Problem/proof_work/negative_valley_seed1_2026_data.json>)保存全部负点与每个优化结果。','- [negative_valley_seed1_2026_summarize.py](</home/dsh/Thomson Problem/proof_work/negative_valley_seed1_2026_summarize.py>)：只分析既有数据，不追加优化；[negative_valley_seed1_2026_summary.json](</home/dsh/Thomson Problem/proof_work/negative_valley_seed1_2026_summary.json>)含簇编号、80位复算、Hessian与聚类间距。','- [negative_valley_seed1_2026_search.log](</home/dsh/Thomson Problem/proof_work/negative_valley_seed1_2026_search.log>)：原始pool/最终摘要。','', '在 /home/dsh/Thomson Problem 中使用：','', '```bash', 'PYTHONPATH=proof_work:proof_work/python_deps OPENBLAS_NUM_THREADS=1 python3 -c "import negative_valley_seed1_2026_search as m; m.PREFIX=\'negative_valley_seed1_2026_replay_\'; m.run()"', '```', '', '复现需换未占用PREFIX；源脚本默认assert输出不存在以保留旧结果。重放轨迹可能受BLAS及SciPy版本影响。原任务环境Python3.10.12、NumPy2.2.6、SciPy1.15.3。', '', '本轮搜索job bash-694已以exit0完成并job_output收齐；没有新增lower bound，没有运行SDP，没有编辑父主报告/manifest。']
    note=ROOT/(PREFIX+'note_zh.md');assert not note.exists();note.write_text('\n'.join(lines)+'\n');print(json.dumps({'valleys':[{'id':r['id'],'R80':r['high_precision_actual_f']['R_decimal_80digit'],'quadratic_halfwidth':r.get('local_quadratic_ellipsoid_coordinate_halfwidth')}for r in rows],'sample_distances':distances,'elapsed_analysis':out['analysis_elapsed_seconds'],'note':str(note)},indent=2))
if __name__=='__main__':main()
